define(['jquery','mage/template','text!Amasty_Base/template/config/form/field/array/row.html'],function($,mageTemplateRenderer,rowTemplate){'use strict';$.widget('mage.amLicenseKeys',{options:{selectors:{licenseKeysContainer:'[data-ambase-license=license-keys-container]',addRowButton:'[data-ambase-license=add-license-key]',},columnNames:[],existingKeys:[],elementName:[]},_create:function(){$(this.options.selectors.addRowButton).on('click',()=>{this.addRow();});if(this.options.existingKeys.length===0){this.addRow();}else{this.options.existingKeys.forEach((existingKey)=>{this.addRow(existingKey);});}},addRow:function(rowData=null){let templateValues;if(rowData){templateValues=rowData;}else{const d=new Date();templateValues={'option_extra_attrs':{},_id:'_'+d.getTime()+'_'+d.getMilliseconds()};this.options.columnNames.forEach((columnName)=>{templateValues[columnName]='';});}
templateValues.columnNames=this.options.columnNames;templateValues.elementName=this.options.elementName;$(this.options.selectors.licenseKeysContainer).append(mageTemplateRenderer(rowTemplate,{data:templateValues}));this.bindRemoveRow(templateValues._id);},bindRemoveRow:function(rowId){$(`#${rowId}`).find('[data-ambase-license=delete-license-key]').on('click',function(){$(`#${rowId}`).remove();});}});return $.mage.amLicenseKeys;});